import{_ as a,o as i,c as n,a3 as t}from"./chunks/framework.Ctn2UYXF.js";const c=JSON.parse('{"title":"P4 · 拓扑排序与并行构建","description":"","frontmatter":{},"headers":[],"relativePath":"principles/04-topological-build.md","filePath":"principles/04-topological-build.md","lastUpdated":1792494191000}'),p={name:"principles/04-topological-build.md"};function e(l,s,h,o,d,r){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="p4-·-拓扑排序与并行构建" tabindex="-1">P4 · 拓扑排序与并行构建 <a class="header-anchor" href="#p4-·-拓扑排序与并行构建" aria-label="Permalink to &quot;P4 · 拓扑排序与并行构建&quot;">​</a></h1><blockquote><p><strong>前置</strong>：读完成 <a href="/pnpm-monorepo-tutorial-pages/05-build-optimization">07 构建流程与缓存优化</a>　|　<strong>配套练习</strong>：<a href="/pnpm-monorepo-tutorial-pages/practice/04-topological-build">E4 拓扑排序与并行调度</a></p></blockquote><p>「为什么我在 <code>packages/ui</code> 改了代码，<code>apps/web</code> 构建时用的还是旧的？」——这类问题的答案往往不在构建工具，而在 <strong>Monorepo 的调度顺序</strong>。</p><h2 id="你将学到" tabindex="-1">你将学到 <a class="header-anchor" href="#你将学到" aria-label="Permalink to &quot;你将学到&quot;">​</a></h2><ul><li>依赖图如何决定「谁先构建」</li><li><code>-r</code> 默认的拓扑序、<code>--parallel</code> 的区别、并发度怎么控</li><li>缓存命中的判定本质（输入指纹）</li><li>三层缓存：TS 增量、Vite 预构建、任务级缓存</li></ul><h2 id="一、依赖图与拓扑序" tabindex="-1">一、依赖图与拓扑序 <a class="header-anchor" href="#一、依赖图与拓扑序" aria-label="Permalink to &quot;一、依赖图与拓扑序&quot;">​</a></h2><p>把 workspace 的每个包看作节点，把 <code>package.json</code> 里的 workspace 依赖看作边：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          ┌──────────────┐</span></span>
<span class="line"><span>          │ packages/types│  ← 无依赖，图的「源点」</span></span>
<span class="line"><span>          └───────┬──────┘</span></span>
<span class="line"><span>        ┌─────────┴──────────┐</span></span>
<span class="line"><span>        ▼                    ▼</span></span>
<span class="line"><span>┌───────────────┐    ┌───────────────┐</span></span>
<span class="line"><span>│ packages/utils│    │   apps/api    │</span></span>
<span class="line"><span>└───────┬───────┘    └───────────────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│  packages/ui  │</span></span>
<span class="line"><span>└───────┬───────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│   apps/web    │  ← 消费最多的「汇点」</span></span>
<span class="line"><span>└───────────────┘</span></span></code></pre></div><p><strong>拓扑序（topological order）</strong> 指：任一节点出现前，它依赖的所有节点都已出现。对本仓库就是 <code>types → utils → ui → web</code>。</p><p>违背拓扑序的后果很具体：<code>apps/web</code> 构建时需要 <code>@tutorial/ui</code> 的产物，而 <code>ui</code> 又需要 <code>utils</code> 的类型定义——<strong>顺序错了，要么报错，要么悄悄用了上一次的旧产物</strong>。</p><h2 id="二、pnpm-的调度行为" tabindex="-1">二、pnpm 的调度行为 <a class="header-anchor" href="#二、pnpm-的调度行为" aria-label="Permalink to &quot;二、pnpm 的调度行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>顺序</th><th>适用场景</th></tr></thead><tbody><tr><td><code>pnpm -r run build</code></td><td><strong>拓扑序</strong>（被依赖者先）</td><td>有产物依赖时（默认行为，最省心）</td></tr><tr><td><code>pnpm -r --parallel run dev</code></td><td>忽略顺序，全部同时启动</td><td>长驻进程（dev server）</td></tr><tr><td><code>pnpm -r run typecheck</code></td><td>拓扑序</td><td>类型检查（跳不过依赖）</td></tr><tr><td><code>pnpm --filter ...@tutorial/types run build</code></td><td>只跑「依赖了 types」的包（含传递依赖者）</td><td>精准重建</td></tr></tbody></table><p>本仓库根 <code>package.json</code> 就是两种策略的对照：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scripts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 显式拓扑：先 packages 层，再 apps 层</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm -r --filter=./packages/* run build &amp;&amp; pnpm -r --filter=./apps/* run build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 无关顺序，全部并行</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm -r --parallel run dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 借助 pnpm 默认的拓扑序</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm -r run test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;typecheck&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pnpm -r run typecheck&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>💡 <code>build</code> 采用「两段 filter」而非单条 <code>-r run build</code>，是一种<strong>显式拓扑</strong>写法：不依赖 pnpm 的排序推断，层级关系一眼可读。当层数变多（如 <code>tools/</code>、<code>examples/</code>）时，这种写法反而更难维护——那时更适合交给 pnpm 的默认拓扑序或任务编排工具。</p></blockquote><p><strong>并发度控制</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace-concurrency</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 限制同时跑 4 个包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace-concurrency</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 串行（等价于严格拓扑，便于排查顺序问题）</span></span></code></pre></div><h2 id="三、缓存的本质-输入指纹" tabindex="-1">三、缓存的本质：输入指纹 <a class="header-anchor" href="#三、缓存的本质-输入指纹" aria-label="Permalink to &quot;三、缓存的本质：输入指纹&quot;">​</a></h2><p>所有「增量构建 / 缓存命中」的机制，本质都是同一件事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入指纹 = hash(源文件内容 + 依赖包的产物 + 构建配置 + 环境变量)</span></span>
<span class="line"><span>命中条件 = 该指纹此前算过，且产物仍在</span></span></code></pre></div><p>因此<strong>缓存失效的常见原因</strong>不是「工具坏了」，而是输入变了：改了一行源码、依赖包重新构建、<code>tsconfig</code> 动了一下、甚至注入了一个新的环境变量。</p><p>三层缓存，粒度从细到粗：</p><table tabindex="0"><thead><tr><th>层次</th><th>载体</th><th>命中后节省</th></tr></thead><tbody><tr><td>类型检查</td><td><code>*.tsbuildinfo</code>（TS <code>incremental</code> / <code>composite</code>）</td><td>跳过未变文件的类型计算</td></tr><tr><td>依赖预构建</td><td><code>node_modules/.vite/</code>（Vite dep pre-bundling）</td><td>跳过第三方依赖的打包</td></tr><tr><td>任务级</td><td><code>.turbo/</code>、<code>.nx/</code> 等（如 Turborepo）</td><td><strong>整个包</strong>的构建任务直接跳过</td></tr></tbody></table><blockquote><p>⚠️ <strong>本仓库现状</strong>：目前 <code>packages/*</code> 的 <code>tsconfig.json</code> <strong>未开启增量</strong>，仓库内也不存在 <code>*.tsbuildinfo</code> 与 <code>node_modules/.vite</code>。也就是说，下面这些优化<strong>是你可以动手加上的</strong>，而不是已经生效的。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*.tsbuildinfo&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -not</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;./node_modules/*&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 当前：无输出</span></span></code></pre></div></blockquote><h2 id="四、落地到本仓库" tabindex="-1">四、落地到本仓库 <a class="header-anchor" href="#四、落地到本仓库" aria-label="Permalink to &quot;四、落地到本仓库&quot;">​</a></h2><p><strong>① 打开 TypeScript 增量</strong>（改 <code>packages/*/tsconfig.json</code>）：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;compilerOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;incremental&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tsBuildInfoFile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dist/.tsbuildinfo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>或使用 <strong>Project References</strong>（<code>composite: true</code> + 根 <code>tsconfig</code> 的 <code>references</code>），让 <code>tsc -b</code> 自动按依赖拓扑构建并复用增量信息。</p><p><strong>② 只跑改动过的包</strong>（CI 提速最有效的一招）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...[origin/main]</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...[origin/main]</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>...[&lt;ref&gt;]</code> 会选出「自该 ref 以来发生变更的包 <strong>及其依赖者</strong>」——注意是<strong>依赖者</strong>（因为它们的产物也依赖被你改动的东西）。</p><p><strong>③ 验证效果</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pnpm build        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第一次</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pnpm build        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第二次：若已开启增量，应明显更快</span></span></code></pre></div><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><ul><li>[ ] 能画出本仓库的依赖图并写出拓扑序</li><li>[ ] 能说清 <code>-r</code>（拓扑）与 <code>--parallel</code>（无序）的适用差异</li><li>[ ] 理解缓存判定 = 输入指纹，而非「工具的黑魔法」</li><li>[ ] 会用 <code>--filter ...[origin/main]</code> 只构建改动包</li><li>[ ] 亲手实现拓扑排序：<a href="/pnpm-monorepo-tutorial-pages/practice/04-topological-build">练习 E4</a></li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/pnpm-monorepo-tutorial-pages/principles/05-changeset-versioning">P5 · Changesets 版本计算</a></li></ul>`,37)])])}const g=a(p,[["render",e]]);export{c as __pageData,g as default};
